<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetAttributes;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetRetrieveUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateAssetVisibilityService $visibility,
    private readonly TemplateAssetReadGateway $reader
  ) {
  }

  public function allowRetrieve(?TemplateAssetRef $ref = null): Allow
  {
    $this->logDebug("Check allow of retrieve usecase for Template asset");
    $span = $this->startSpan("Check allow of retrieve usecase for Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function hiddenFields(?TemplateAssetRef $ref = null): array
  {
    $this->logDebug("Check hidden fields usecase for Template asset");
    $span = $this->startSpan("Check hidden fields usecase for Template asset");
    try {
      return $this->visibility->fieldsToHide($ref);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieve(string $uid): TemplateAssetRetrieveResult
  {
    $this->logDebug("Run retrieve usecase for Template asset");
    $span = $this->startSpan("Run retrieve usecase for Template asset");
    try {
      $ref = new TemplateAssetRef($uid);
      $allow = $this->allowRetrieve($ref);
      if( !$allow->allowed ) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Template asset');
      }
      if (!$result = $this->visibility->retrieveVisible($ref)) {
        throw new NotFoundException($uid);
      }
      $output = $this->visibility->copyWithHidden(          $this->visibility->prepareVisibleData( $result ) );
      return new TemplateAssetRetrieveResult($output);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveContent(string $uid): BinaryContent
  {
    $this->logDebug("Run retrieve Content file usecase for Template asset");
    $span = $this->startSpan("Run retrieve Content file usecase for Template asset");
    try {
      $ref = new TemplateAssetRef($uid);
      $allow = $this->allowRetrieve($ref);
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve content of Template asset');
      }
      if (!$visible = $this->visibility->retrieveVisible($ref)) {
        throw new NotFoundException($uid);
      }
      $url = $visible->getContent();
      if (null === $url ) {
        throw new NotFoundException($uid);
      }
      return $this->reader->readContent( $url );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
